// Input data format: { "data": [1,0,1,0,0], "solved": false, "wrong":false }

var states = msg.payload.data;
var isSolved = msg.payload.solved;

function toBool(val) {
    return val == 1;
}

// Send status to the 5 dashboard LEDs
var msg1 = { payload: toBool(states[0]) };
var msg2 = { payload: toBool(states[1]) };
var msg3 = { payload: toBool(states[2]) };
var msg4 = { payload: toBool(states[3]) };
var msg5 = { payload: toBool(states[4]) };

// Status text for the dashboard
var msgSolved = { payload: isSolved ? "PUZZLE SOLVED!" : "Waiting..." };

return [msg1, msg2, msg3, msg4, msg5, msgSolved];

var statusArray = msg.payload.data;
var isSolved = msg.payload.solved;
var isWrong = msg.payload.wrong || false;

var lastSentLights = flow.get('lastSentLights') || [0, 0, 0, 0, 0];
var lastSolved = flow.get('lastSolved') || false;
var isAnimPlaying = flow.get('isAnimPlaying') || false;

var msgsToSend = []; // Unified broadcast packet

// 0. Wrong placement alarm
if (isWrong) msgsToSend.push({ topic: "/cue/WRONG/start", payload: "" });

// 1. Solved / reset state handling
if (isSolved !== lastSolved) {
    if (isSolved === true) {
        // 1. Starting signal: launch the timeline trigger
        msgsToSend.push({ topic: "/ritual/timeline/start", payload: "" });

        // 2. Dramatic blackout: force all 5 individual lights OFF
        //    while the downstream effects system takes over
        for (let i = 0; i < 5; i++) {
            msgsToSend.push({ topic: "/ritual/light/" + (i + 1), payload: 0 });
            lastSentLights[i] = 0; // Store the current OFF state
        }

        // Note: the actual animation trigger is no longer sent here.
        // It is now handled by the dedicated timeline branch below.
        flow.set('isAnimPlaying', true); // Internal state marker only
    } else {
        // Reset the game: send 0 to turn off all individual lights
        for (var j = 1; j <= 5; j++) msgsToSend.push({ topic: "/ritual/light/" + j, payload: 0 });

        // Absolute OFF: stop WinAnimation unconditionally (Flash mode, idempotent)
        msgsToSend.push({ topic: "/ritual/win_anim", payload: 0 });

        msgsToSend.push({ topic: "/cue/WIN/cancel", payload: "" });
        msgsToSend.push({ topic: "/cue/WIN/stop", payload: "" });

        lastSentLights = [0, 0, 0, 0, 0];
        flow.set('isAnimPlaying', false);
    }

    flow.set('lastSolved', isSolved);
    flow.set('lastSentLights', lastSentLights);
}

// 2. Normal item placement logic
if (!isSolved) {
    for (let i = 0; i < 5; i++) {
        if (statusArray[i] !== lastSentLights[i]) {
            if (statusArray[i] === 1) msgsToSend.push({ topic: "/cue/CANDLE/start", payload: "" });

            // [Brightness Protection]: Converts the value '1' received from Arduino into '255', 
            //ensuring that the lighting within QLC+ reaches 100% full brightness.
            var brightness = (statusArray[i] === 1) ? 255 : 0;
            msgsToSend.push({ topic: "/ritual/light/" + (i + 1), payload: brightness });

            lastSentLights[i] = statusArray[i];
        }
    }
    flow.set('lastSentLights', lastSentLights);
}

// Unified output: send all accumulated commands in a single packet
if (msgsToSend.length > 0) {
    return [msgsToSend];
}
return null;

var msgs = [];

// Absolute ON: value 255 starts the WinAnimation in QLC+ (Flash mode)
msgs.push({ topic: "/ritual/win_anim", payload: 255 });

// Trigger audio
msgs.push({ topic: "/cue/WIN/start", payload: "" });

return [msgs];

flow.set('isAnimPlaying', false);
var msgs = [];

// Absolute OFF: value 0 stops the WinAnimation in QLC+ (Flash mode)
msgs.push({ topic: "/ritual/win_anim", payload: 0 });

// Restore all 5 fixtures to full brightness
for (var i = 1; i <= 5; i++) {
    msgs.push({ topic: "/ritual/light/" + i, payload: 255 });
}
return [msgs];

const GAME_MINUTES = 5; 
const VIDEO_SECONDS = 8; // video 
const AUDIO_SECONDS = 29; // sound track
const BUFFER_SECONDS = VIDEO_SECONDS + AUDIO_SECONDS; // total buffrt time
const TOTAL_SECONDS = (GAME_MINUTES * 60) + BUFFER_SECONDS;

// get current state
var state = flow.get('timerState') || 'IDLE';
var timeRemaining = flow.get('timeRemaining') || 0;
var msgsToSend = [];

// --- handle the command from the game clock button ---
if (msg.payload === 'START') {
    state = 'RUNNING';
    timeRemaining = TOTAL_SECONDS;
    flow.set('timerState', state);
    flow.set('timeRemaining', timeRemaining);

    // action：trigger QLab play video (and the countdown sound track will auto follow)
    msgsToSend.push({ topic: "/cue/PREGAME/start", payload: "" });
    return [null, msgsToSend];
}

if (msg.payload === 'STOP') {
    state = 'IDLE';
    timeRemaining = TOTAL_SECONDS;
    flow.set('timerState', state);
    flow.set('timeRemaining', timeRemaining);

    // stop any sound or video playing in QLab 
    msgsToSend.push({ topic: "/panic", payload: "" }); 
    msgsToSend.push({ topic: "/cue/PREGAME/stop", payload: "" });
    msgsToSend.push({ topic: "/cue/GAME_START/stop", payload: "" });

    // reset the time display 
    return [{ payload: formatTime(GAME_MINUTES * 60), color: "#FFFFFF" }, msgsToSend];
}

// --- (TICK) ---
if (msg.payload === 'TICK' && state === 'RUNNING') {
    timeRemaining--;
    flow.set('timeRemaining', timeRemaining);

    // while video and audio are playing，time will be locked in 60:00
    var displaySeconds = timeRemaining > (GAME_MINUTES * 60) ? (GAME_MINUTES * 60) : timeRemaining;
    var displayTime = formatTime(displaySeconds);

    var uiColor = "#3498DB"; // defaue blue  (buffer time, video and sound are playing)

    // key time：

    // 1. the moment (buffer time ends，video and sound end and just rigt begin at 60:00)
    if (timeRemaining === (GAME_MINUTES * 60)) {

        // UI's color is change to green, remind gm game begins
        uiColor = "#2ECC71"; // turn green
    }

    // 2. game is on going
    else if (timeRemaining < (GAME_MINUTES * 60) && timeRemaining > 120) {
        uiColor = "#2ECC71"; // green
    }

    // 3. last 10min sound track reminder
    else if (timeRemaining === 120) {
        msgsToSend.push({ topic: "/cue/REMINDER_10M/start", payload: "" });
        uiColor = "#E74C3C"; // turn red
    }

    // 4. last 10 min -> red
    else if (timeRemaining < 120) {
        uiColor = "#E74C3C";
    }

    // 5. time up
    if (timeRemaining <= 0) {
        state = 'IDLE';
        flow.set('timerState', state);
        msgsToSend.push({ topic: "/cue/TIME_UP/start", payload: "" });
        displayTime = "00:00";
    }

    return [{ payload: displayTime, color: uiColor }, msgsToSend.length ? msgsToSend : null];
}

return null;

// farmat time MM:SS
function formatTime(totalSeconds) {
    var m = Math.floor(totalSeconds / 60);
    var s = totalSeconds % 60;
    return (m < 10 ? "0" : "") + m + ":" + (s < 10 ? "0" : "") + s;
}

// Deduplicate: only pass if serial payload has actually changed
// Filters out repeated identical heartbeat messages
var last = flow.get('lastSerialPayload');
var current = JSON.stringify(msg.payload);
if (current !== last) {
    flow.set('lastSerialPayload', current);
    return msg;
}
return null;
